//! Device plan -> Rust source.

use std::fmt::Write as _;

use daedalus_mcu::Overflow;

use crate::CompileOptions;
use crate::lower::{InputSource, McuPlan, PlanNode};

const MCU: &str = "::daedalus_mcu";

impl McuPlan {
    /// Render the plan as a Rust module body for `include!` in the device crate.
    pub fn to_rust(&self, options: &CompileOptions) -> String {
        let mut out = String::new();
        let name = &options.graph_name;
        let _ = writeln!(
            out,
            "// @generated by daedalus-mcu-build from plan {:016x}; do not edit.\n",
            self.hash
        );
        let _ = writeln!(
            out,
            "/// Stable hash of the host plan this module was generated from."
        );
        let _ = writeln!(out, "pub const PLAN_HASH: u64 = {:#x};", self.hash);
        let node_ids: Vec<String> = self.nodes.iter().map(|n| format!("{:?}", n.name)).collect();
        let _ = writeln!(
            out,
            "/// Nodes in schedule order (`McuError::Node::node`).\n\
             pub const NODE_IDS: [&str; {}] = [{}];",
            node_ids.len(),
            node_ids.join(", ")
        );
        let edge_labels: Vec<String> = self
            .edges
            .iter()
            .map(|e| format!("{:?}", e.label))
            .collect();
        let _ = writeln!(
            out,
            "/// Edges (`McuError::QueueFull::edge`).\n\
             pub const EDGES: [&str; {}] = [{}];\n",
            edge_labels.len(),
            edge_labels.join(", ")
        );

        let _ = writeln!(
            out,
            "/// The planned graph: one queue per edge, one state slot per node."
        );
        let _ = writeln!(out, "pub struct {name} {{\n    tick: u32,");
        for (i, edge) in self.edges.iter().enumerate() {
            let _ = writeln!(
                out,
                "    /// {}\n    e{i}: {MCU}::Queue<{}, {}>,",
                edge.label, edge.ty, edge.capacity
            );
        }
        for (i, node) in self.nodes.iter().enumerate() {
            let _ = writeln!(out, "    s{i}: ::{}::State,", node.path);
        }
        out.push_str("}\n\n");

        let _ = writeln!(
            out,
            "impl Default for {name} {{\n    fn default() -> Self {{\n        Self::new()\n    }}\n}}\n"
        );
        let _ = writeln!(
            out,
            "#[allow(clippy::clone_on_copy, clippy::redundant_clone, unused_variables)]"
        );
        let _ = writeln!(out, "impl {name} {{");
        out.push_str("    pub const fn new() -> Self {\n        Self {\n            tick: 0,\n");
        for i in 0..self.edges.len() {
            let _ = writeln!(out, "            e{i}: {MCU}::Queue::new(),");
        }
        for (i, node) in self.nodes.iter().enumerate() {
            let _ = writeln!(
                out,
                "            s{i}: <::{}::State as {MCU}::NodeState>::INIT,",
                node.path
            );
        }
        out.push_str("        }\n    }\n");

        for port in &self.host_inputs {
            let _ = writeln!(
                out,
                "\n    /// Push a value into host input `{}`.\n    \
                 pub fn push_{}(&mut self, value: {}) -> Result<(), {MCU}::McuError> {{",
                port.name,
                ident(&port.name),
                port.ty
            );
            self.emit_pushes(&mut out, "value", &port.edges, 2);
            out.push_str("        Ok(())\n    }\n");
        }
        for port in &self.host_outputs {
            let edge = port.edges[0];
            let _ = writeln!(
                out,
                "\n    /// Pop the oldest value of host output `{}`.\n    \
                 pub fn pop_{}(&mut self) -> Option<{}> {{\n        self.e{edge}.pop()\n    }}",
                port.name,
                ident(&port.name),
                port.ty
            );
        }

        let _ = writeln!(
            out,
            "\n    /// Run every node once in schedule order (`Ctx::now_micros` is 0).\n    \
             pub fn tick(&mut self) -> Result<(), {MCU}::McuError> {{\n        self.tick_at(0)\n    }}\n\n    \
             /// [`Self::tick`] with the time read from `clock`.\n    \
             pub fn tick_with(&mut self, clock: &impl {MCU}::Clock) -> Result<(), {MCU}::McuError> {{\n        \
             self.tick_at({MCU}::Clock::now_micros(clock))\n    }}\n\n    \
             /// [`Self::tick`] at time `now_micros`.\n    \
             pub fn tick_at(&mut self, now_micros: u64) -> Result<(), {MCU}::McuError> {{\n        \
             let ctx = {MCU}::Ctx {{ tick: self.tick, now_micros }};\n        \
             self.tick = self.tick.wrapping_add(1);"
        );
        for (i, node) in self.nodes.iter().enumerate() {
            self.emit_node(&mut out, i, node);
        }
        out.push_str("        Ok(())\n    }\n}\n");
        out
    }

    fn emit_node(&self, out: &mut String, index: usize, node: &PlanNode) {
        let _ = writeln!(out, "        // {}", node.name);
        let (open, take) = if node.wait_all {
            // Fire mode `all`: peek every required edge, then pop one value per edge.
            let held: Vec<String> = node
                .inputs
                .iter()
                .filter_map(|input| match input {
                    InputSource::Edge {
                        edge,
                        required: true,
                    } => Some(format!("!self.e{edge}.is_empty()")),
                    _ => None,
                })
                .collect();
            (format!("        if {} {{\n", held.join(" && ")), "pop")
        } else {
            ("        {\n".to_string(), "take_oldest")
        };
        out.push_str(&open);
        let mut required = Vec::new();
        let mut args = Vec::new();
        for (k, input) in node.inputs.iter().enumerate() {
            match input {
                InputSource::Edge {
                    edge,
                    required: is_required,
                } => {
                    let _ = writeln!(out, "            let i{k} = self.e{edge}.{take}();");
                    if *is_required {
                        required.push(format!("i{k}"));
                    }
                    args.push(format!("i{k}"));
                }
                InputSource::Const {
                    expr,
                    required: true,
                } => args.push(expr.clone()),
                InputSource::Const {
                    expr,
                    required: false,
                } => args.push(format!("Some({expr})")),
                InputSource::Absent => args.push("None".into()),
            }
        }
        let mut depth = 3;
        if !required.is_empty() {
            let _ = if let [single] = required.as_slice() {
                writeln!(out, "            if let Some({single}) = {single} {{")
            } else {
                let pattern: Vec<String> = required.iter().map(|v| format!("Some({v})")).collect();
                writeln!(
                    out,
                    "            if let ({}) = ({}) {{",
                    pattern.join(", "),
                    required.join(", ")
                )
            };
            depth = 4;
        }
        let pad = "    ".repeat(depth);
        let _ = writeln!(
            out,
            "{pad}let out = ::{}::run(&mut self.s{index}, &ctx, {}).map_err(|error| \
             {MCU}::McuError::Node {{ node: {index}, error }})?;",
            node.path,
            args.join(", ")
        );
        for (k, edges) in node.outputs.iter().enumerate() {
            if edges.is_empty() {
                continue;
            }
            let _ = writeln!(out, "{pad}if let Some(value) = out.{k} {{");
            self.emit_pushes(out, "value", edges, depth + 1);
            let _ = writeln!(out, "{pad}}}");
        }
        if !required.is_empty() {
            out.push_str("            }\n");
        }
        out.push_str("        }\n");
    }

    /// Push `value` into each of `edges` (cloned for all but the last), widening where planned.
    fn emit_pushes(&self, out: &mut String, value: &str, edges: &[usize], depth: usize) {
        let pad = "    ".repeat(depth);
        for (n, &edge) in edges.iter().enumerate() {
            let plan = &self.edges[edge];
            let mut item = if n + 1 < edges.len() {
                format!("{value}.clone()")
            } else {
                value.to_string()
            };
            if plan.widen {
                item = format!("<{} as ::core::convert::From<_>>::from({item})", plan.ty);
            }
            let overflow = match plan.overflow {
                Overflow::DropOldest => "DropOldest",
                Overflow::DropNewest => "DropNewest",
                Overflow::Error => "Error",
            };
            let push = format!("self.e{edge}.push({item}, {MCU}::Overflow::{overflow})");
            let _ = if plan.overflow == Overflow::Error {
                writeln!(
                    out,
                    "{pad}{push}.map_err(|_| {MCU}::McuError::QueueFull {{ edge: {edge} }})?;"
                )
            } else {
                writeln!(out, "{pad}let _ = {push};")
            };
        }
    }
}

/// A port name as an identifier fragment (`push_<port>` / `pop_<port>`).
fn ident(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect()
}
